package web

const chatPageHTML = `<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Day 19 · MCP Pipeline</title>
<style>
:root{color-scheme:dark;--bg:#0b0d12;--panel:#151922;--panel2:#0f131b;--line:#2c3442;--ink:#f6f2e8;--muted:#929cad;--cyan:#5ce1e6;--amber:#ffca62;--green:#9dec83;--red:#ff7b82}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 10% 0,#172535 0,transparent 34%),radial-gradient(circle at 90% 12%,#282014 0,transparent 30%),var(--bg);color:var(--ink);font:15px/1.5 Inter,system-ui,sans-serif}main{width:min(1320px,calc(100% - 32px));margin:0 auto;padding:34px 0 52px}.hero{display:flex;justify-content:space-between;gap:24px;align-items:end;margin-bottom:22px}.kicker{color:var(--cyan);font:800 11px/1.2 monospace;letter-spacing:.18em;text-transform:uppercase}.hero h1{margin:8px 0 10px;font:700 clamp(35px,6vw,68px)/.93 Georgia,serif;letter-spacing:-.045em}.hero p{color:var(--muted);max-width:760px;margin:0}.badge{white-space:nowrap;border:1px solid var(--line);padding:10px 14px;border-radius:999px;background:#111620}.pipeline{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:0 0 18px}.step{position:relative;border:1px solid var(--line);border-radius:13px;padding:13px 14px;background:var(--panel)}.step:not(:last-child):after{content:'→';position:absolute;right:-15px;top:12px;z-index:2;color:var(--amber);font-weight:900}.step b{display:block;color:var(--cyan);font:700 13px monospace}.step span{color:var(--muted);font-size:12px}.grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(380px,.9fr);gap:16px}.card{border:1px solid var(--line);border-radius:18px;background:rgba(21,25,34,.94);padding:18px;box-shadow:0 28px 80px #0005}.head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px}.head h2{margin:0;font-size:12px;text-transform:uppercase;letter-spacing:.13em}.head small{color:var(--muted)}.examples{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:10px}button{border:0;border-radius:10px;padding:10px 13px;background:var(--cyan);color:#071013;font-weight:800;cursor:pointer}.example,.reset{background:#242b37;color:var(--ink);border:1px solid #384355;font-size:12px;padding:7px 10px}button:disabled{opacity:.45;cursor:wait}textarea{width:100%;min-height:112px;resize:vertical;border:1px solid #3a4556;border-radius:12px;background:var(--panel2);color:var(--ink);padding:13px;font:inherit;outline:none}textarea:focus{border-color:var(--cyan)}.send{width:100%;margin-top:9px}.dialog,.trace{display:grid;gap:8px;max-height:475px;overflow:auto}.dialog{min-height:142px;margin-top:16px;padding:11px;background:var(--panel2);border-radius:12px}.bubble{padding:10px 12px;border-radius:11px;white-space:pre-wrap;max-width:94%}.user{justify-self:end;background:#243543}.assistant{justify-self:start;background:#28271f}.event{border:1px solid #303a49;border-left:3px solid var(--cyan);border-radius:10px;padding:10px;background:var(--panel2)}.event strong{font:800 11px monospace;color:var(--cyan)}.event.done{border-left-color:var(--green)}pre{white-space:pre-wrap;overflow-wrap:anywhere;margin:7px 0 0;color:#bdc6d3;font:11px/1.45 monospace}.files{grid-column:1/-1}.file-grid{display:grid;grid-template-columns:340px 1fr;gap:14px}.file-list{display:grid;gap:7px;align-content:start}.file{width:100%;text-align:left;background:#202734;color:var(--ink);border:1px solid var(--line)}.file small{display:block;color:var(--muted);font-weight:400}.preview{min-height:180px;max-height:460px;overflow:auto;background:var(--panel2);border:1px solid var(--line);border-radius:12px;padding:14px;white-space:pre-wrap;font:13px/1.55 monospace}.empty,.muted{color:var(--muted)}.error{color:var(--red)}@media(max-width:900px){.hero{display:block}.badge{display:inline-block;margin-top:14px}.grid,.file-grid{grid-template-columns:1fr}.files{grid-column:auto}}
</style></head><body><main>
<section class="hero"><div><div class="kicker">Day 19 · model-orchestrated composition</div><h1>Research Pipeline</h1><p>Агент сам связывает три независимых MCP‑инструмента. Полный trace показывает реальные документы, точную передачу summary и результат атомарной записи.</p></div><div class="badge">● Streamable HTTP · tool_choice: auto</div></section>
<section class="pipeline"><div class="step"><b>01 / search</b><span>Wikipedia → документы</span></div><div class="step"><b>02 / summarize</b><span>Документы → extractive summary</span></div><div class="step"><b>03 / save_to_file</b><span>Summary → безопасный Markdown</span></div></section>
<section class="grid"><div class="card"><div class="head"><h2>Естественный запрос</h2><small>DeepSeek выбирает tools</small></div><div class="examples"><button class="example" data-prompt="Найди информацию о Model Context Protocol, подготовь краткую сводку на русском языке и сохрани её в файл mcp-summary.md.">MCP</button><button class="example" data-prompt="Найди информацию о языке Go, сделай сводку на русском и сохрани в файл golang-summary.md.">Go</button><button class="example" data-prompt="Find information about Alan Turing, summarize it in English and save it to turing-summary.md.">English</button></div><textarea id="message">Найди информацию о Model Context Protocol, подготовь краткую сводку на русском языке и сохрани её в файл mcp-summary.md.</textarea><button id="send" class="send">Запустить пайплайн</button><div class="head" style="margin-top:19px"><h2>История диалога</h2><button id="reset" class="reset">Новый диалог</button></div><div id="dialog" class="dialog"><div class="empty">История появится здесь.</div></div></div>
<div class="card"><div class="head"><h2>MCP trace</h2><small id="sequence">Ожидается запуск</small></div><div id="trace" class="trace"><div class="empty">Здесь будут аргументы и результаты каждого шага.</div></div></div>
<div class="card files"><div class="head"><h2>Сохранённые Markdown‑файлы</h2><small id="file-count">0 файлов</small></div><div class="file-grid"><div id="files" class="file-list"><div class="empty">Загрузка…</div></div><div id="preview" class="preview muted">Выберите файл, чтобы безопасно открыть его содержимое.</div></div></div></section>
</main><script>
const $=s=>document.querySelector(s),message=$('#message'),send=$('#send'),dialog=$('#dialog'),trace=$('#trace'),files=$('#files'),preview=$('#preview');document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>message.value=b.dataset.prompt);
function bubble(role,text,extra=''){if(dialog.querySelector('.empty'))dialog.innerHTML='';const e=document.createElement('div');e.className='bubble '+role+' '+extra;e.textContent=text;dialog.append(e);dialog.scrollTop=dialog.scrollHeight;return e}
async function history(){try{const r=await fetch('/api/chat/history'),d=await r.json();dialog.innerHTML='';(d.messages||[]).forEach(m=>bubble(m.role,m.content));if(!d.messages?.length)dialog.innerHTML='<div class="empty">История появится здесь.</div>'}catch{dialog.innerHTML='<div class="error">Не удалось загрузить историю.</div>'}}
function renderTrace(items){trace.innerHTML='';const order=[];for(const x of items||[]){const e=document.createElement('div');e.className='event '+(x.stage==='mcp/tools/call'?'done':'');const title=document.createElement('strong');title.textContent=x.stage+(x.tool?' · '+x.tool:'')+(x.tool_call_id?' · '+x.tool_call_id:'');e.append(title);const note=document.createElement('div');note.textContent=x.message;e.append(note);const detail=x.arguments??x.result;if(detail!==undefined){const p=document.createElement('pre');p.textContent=JSON.stringify(detail,null,2);e.append(p)}trace.append(e);if(x.stage==='model/tool_call')order.push(x.tool)}$('#sequence').textContent=order.length?order.join(' → '):'Нет tool calls'}
async function refreshFiles(){try{const r=await fetch('/api/files'),d=await r.json();files.innerHTML='';$('#file-count').textContent=(d.files||[]).length+' файлов';if(!d.files?.length){files.innerHTML='<div class="empty">Файлов пока нет.</div>';return}for(const f of d.files){const b=document.createElement('button');b.className='file';const name=document.createElement('span');name.textContent=f.name;const meta=document.createElement('small');meta.textContent=f.bytes+' байт · '+new Date(f.modified_at).toLocaleString('ru-RU');b.append(name,meta);b.onclick=()=>openFile(f.name);files.append(b)}}catch(e){files.innerHTML='<div class="error">'+e.message+'</div>'}}
async function openFile(name){preview.className='preview muted';preview.textContent='Загрузка…';try{const r=await fetch('/api/files/'+encodeURIComponent(name)),d=await r.json();if(!r.ok)throw new Error(d.error);preview.className='preview';preview.textContent=d.content}catch(e){preview.className='preview error';preview.textContent=e.message}}
send.onclick=async()=>{const prompt=message.value.trim();if(!prompt)return;send.disabled=true;bubble('user',prompt);const wait=bubble('assistant','Агент выполняет search → summarize → save_to_file…','muted');trace.innerHTML='<div class="empty">DeepSeek получает tools/list и выбирает первый шаг…</div>';try{const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:prompt})}),d=await r.json();if(!r.ok)throw new Error(d.error||'Ошибка запроса');wait.className='bubble assistant';wait.textContent=d.content;renderTrace(d.trace);await refreshFiles()}catch(e){wait.className='bubble assistant error';wait.textContent=e.message}finally{send.disabled=false}}
$('#reset').onclick=async()=>{await fetch('/api/chat/session',{method:'DELETE'});dialog.innerHTML='<div class="empty">Начат новый диалог.</div>';trace.innerHTML='<div class="empty">Здесь будут аргументы и результаты каждого шага.</div>';$('#sequence').textContent='Ожидается запуск'};history();refreshFiles();
</script></body></html>`
